// Conteúdo das quests: "A Origem das Brumas". Cinco cidades, três quests cada, cinco Baús Selados,
// cinco Fragmentos do Mapa e a quest final. O motor fica em quests.js.
//
// Passos (t):
//   talk    falar com um NPC (npc, say, btn)
//   kill    derrotar monstros (need: {tipo: n}) e/ou juntar itens de quest que caem deles (items: [{k, name, n, from, ch}])
//   boss    vencer um chefe (pelo portal/arena ou no mundo)
//   obj     usar um objeto do mapa (obj); lock: {flags, say} exige pistas/chaves
//   seq     usar objetos numa ordem (order); errar recomeça e pode soltar monstros (fail)
//   set     acender só os certos (right) entre vários (objs), em qualquer ordem
//   all     usar todos (objs), em qualquer ordem
//   hotcold achar o objeto certo entre vários (quente/frio)
//   rotate  girar objetos até todos apontarem para o lugar certo (states, target)
//   answer  digitar a resposta (npc ou obj): ans = respostas aceitas
//   choice  escolher um caminho (opts); choiceFinal na quest dá o prêmio de cada escolha
//   awaken  abrir o portal do Colosso Desperto (quest final)
// give: {gold, xp (em níveis: 1 = um nível inteiro, 0.4 = 40% do nível atual), items, chest, flags, title, cos, toAll, bonusHour, loot:{region, lv, n}}
'use strict';

